details.command:
echo "=== Final Verification ===" && \
echo -e "
1. StatefulSet:" && kubectl get statefulset app -n default -o jsonpath='{range .status}
Replicas: {\.replicas} | Ready: {\.availableReplicas}/{\.readyReplicas}
Updated: {\.updatedReplicas}
Available: {\.availableReplicas}
{end}' && \
echo -e "
2. PVCs (must all be Bound):" && kubectl get pvc -n default 2>&1 | grep -E "STATUS|standard" && \
echo -e "
3. Pods (must all be Running, READY=1/1):" && kubectl get pods -n default -l app=app 2>&1

details.stderr:
error: error parsing jsonpath {range .status}
Replicas: {\.replicas} | Ready: {\.availableReplicas}/{\.readyReplicas}
Updated: {\.updatedReplicas}
Available: {\.availableReplicas}
{end}, unrecognized character in action: U+005C ''
